using System;
namespace Downfield {
public partial class Simulation {
 public bool PendingTrickExchange {get{return !UseCustom&&((Playbook==24||Playbook==26||Playbook==32||Playbook==45||Playbook==46)&&trickStage==0||Playbook==27&&trickStage<2);}} public bool TrickPasser;int trickStage;float trickTime;
 public static bool WildcatCall(int p){return p==29||p==30||p==31||p==36||p==44||p==45;}
 public static bool TrickRun(int p){return p==24||p==25||p==26||p==27||p==28||WildcatCall(p)||p==32||p==35||p==38||p==39||p==42||p==43||p==46||p==47;}
 public static string PlayTip(int p){switch(p){case 24:case 45:return "GIVE > PITCH BACK > THROW";case 25:case 35:case 42:case 43:return "BACKWARD TOSS > BACK CAN PASS";case 26:case 27:case 46:return "FOLLOW THE REVERSE EXCHANGES";case 28:return "FAKE THROW > DELAYED GIVE";case 29:case 36:case 44:return "RB TAKES SNAP / FOLLOW GOLD";case 30:return "RB AT QB / THROW OR RUN";case 31:case 38:return "KEEP OR LB GIVE / LB PITCH";case 32:return "RB > WR > THROW TO QB";case 33:return "CATCH > LB PITCH TO SUPPORT";case 34:return "QUICK SHOVEL / PASS TO BACK";case 37:return "FAKE JET > SCREEN";case 47:return "QB KEEPS / BACKS SELL FAKES";default:return IsRunCall(p)?"FOLLOW THE GOLD RUN LANE":"ICON PASS / TAP LOB / HOLD BULLET";}}
 void PrepareCallPersonnel(){if(State!=Phase.PreSnap)return;TrickPasser=false;trickStage=0;trickTime=0;bool wild=WildcatCall(Playbook)&&!UseCustom;if(Franchise!=null&&!EmergencyChoicePending){if(wild&&!Wildcat){ClubPlayer rb=Franchise.Squad(Franchise.UserTeam).Find(p=>p.Role=="RB"&&p.InjuryWeeks==0&&p.Slot==1)??Franchise.Squad(Franchise.UserTeam).Find(p=>p.Role=="RB"&&p.InjuryWeeks==0);if(rb!=null){PutAtQuarterback(rb);FillWildcatBack(rb.Id);}}else if(!wild&&Wildcat&&Franchise.Squad(Franchise.UserTeam).Exists(p=>p.Role=="QB"&&p.InjuryWeeks==0)){Setup();}}if(wild){Wildcat=true;TrickPasser=true;EmergencyPasser=Franchise!=null&&!Franchise.Squad(Franchise.UserTeam).Exists(p=>p.Role=="QB"&&p.InjuryWeeks==0);}if(Playbook==28||Playbook==37||Playbook==47){Controlled.Pose="fake";Controlled.PoseTime=.7f;}}
 void StartTrick(){trickStage=0;trickTime=0;TrickPasser=WildcatCall(Playbook);if(Playbook==28||Playbook==37||Playbook==47){Players[0].Pose="fake";Players[0].PoseTime=.7f;}}
 bool PitchTo(Player receiver){if(receiver==null||!receiver.Active||State!=Phase.Live||HandoffPending||receiver==Controlled||receiver.Z>=Controlled.Z-.05f)return false;target=receiver;lateral=true;passLob=false;Charging=false;toX=receiver.X;toZ=receiver.Z;passDuration=Clamp(Distance(Controlled.X,Controlled.Z,toX,toZ)/19,.25f,.7f);StartFlight("BACKWARD PITCH / #"+receiver.Number);return true;}
 void TickTrick(float dt){if(Playbook<24||UseCustom)return;trickTime+=dt;if(State!=Phase.Live||HandoffPending||BallCrossedScrimmage)return;if((Playbook==24||Playbook==45)&&HandoffOccurred&&trickStage==0&&trickTime>.9f){if(PitchTo(Players[0]))trickStage++;}
  if((Playbook==25||Playbook==35||Playbook==42||Playbook==43)&&HandoffOccurred&&Controlled!=Players[0]){TrickPasser=true;RunPlay=false;}
  if((Playbook==26||Playbook==27||Playbook==32||Playbook==46)&&HandoffOccurred&&trickStage==0&&trickTime>.9f){Player partner=Playbook==32?Players[10]:Players[1];if(partner==Controlled)partner=Players[10];if(PitchTo(partner))trickStage++;}
  if(Playbook==27&&trickStage==1&&trickTime>1.8f&&Controlled==Players[1]){if(PitchTo(Players[2]))trickStage++;}
  if(Playbook==32&&trickStage==1&&Controlled==Players[10]){TrickPasser=true;RunPlay=false;}
 }
 float[] TrickRoute(Player p,float t){if(Playbook<24||UseCustom)return null;if(Playbook==37&&p.StartX==-10&&t<.9f)return new float[]{15,Spot-2};if(Playbook==47&&p.Role=="RB"&&t<1)return new float[]{-6,Spot-4};if(Playbook==47&&p.StartX==-10&&t<1.1f)return new float[]{6,Spot-3};float side=p.StartX<0?-1:1;int route=(Playbook-24)%8;bool support=Playbook==26||Playbook==27||Playbook==32||Playbook==46;if(Playbook==32&&p.Role=="WR"&&p.StartX==-10)return new float[]{12,Spot-9};if(support&&p.Role=="RB")return new float[]{8,Spot-8};if(Playbook==27&&p==Players[2])return new float[]{-14,Spot-10};if(Playbook==32&&p.Role=="QB")return new float[]{16,Spot+Math.Min(14,t*4)};if(Playbook==33&&p.Role=="RB")return new float[]{-8,Spot+Math.Min(12,t*5)};if(Playbook==34&&p.Role=="RB")return new float[]{2,Spot+2};if(Playbook==37||Playbook==40||Playbook==41){if(p.Role=="RB"||Playbook==40&&p.Role=="TE"||Playbook==41&&p==Players[10])return new float[]{side*20,Spot+1.5f};}
  if(p.Role=="RB"&&RunPlay)return RunPoint(t);float z=Spot+Math.Min(42,t*p.Speed);switch(route){case 0:return new float[]{t<1.2f?p.StartX:-side*12,z};case 1:return new float[]{t<1?p.StartX:side*25,Spot+Math.Min(16,t*p.Speed)};case 2:return new float[]{t<1.6f?p.StartX:-side*17,z};case 3:return new float[]{t<1?p.StartX:side*23,z};case 4:return new float[]{t<1?p.StartX:-side*20,Spot+Math.Min(7,t*p.Speed)};case 5:return new float[]{p.StartX,Spot+Math.Min(12,t*p.Speed)};case 6:return new float[]{t<1.2f?p.StartX:side*20,z};default:return new float[]{t<.8f?p.StartX:0,Spot+Math.Min(22,t*p.Speed)};}}
 public float[] TrickRunPoint(float t){float lane=Playbook==26||Playbook==27||Playbook==36||Playbook==46?-19:Playbook==29?4:Playbook==44?22:Playbook==47?-5:12;return new float[]{lane*Math.Min(1,t/1.7f),Spot+Math.Min(35,t*7)};}
}
